#!/usr/bin/env python3
"""V7.3 Arena V2 opponent move/card visual-event clustering."""


def _replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label} expected one match, found {count}")
    return text.replace(old, new, 1)


def apply_arena_perception_events_patch(text):
    old = '''ARENA_LEARNING_FILE = PROFILE_DIR / "arena_learning_model.json"\nARENA_TRACE_FILE = PROFILE_DIR / "arena_battle_trace.jsonl"\nVISION_ADAPTIVE_FILE = PROFILE_DIR / "vision_adaptive.json"\n'''
    new = '''ARENA_LEARNING_FILE = PROFILE_DIR / "arena_learning_model.json"\nARENA_TRACE_FILE = PROFILE_DIR / "arena_battle_trace.jsonl"\nARENA_EVENT_DIR = PROFILE_DIR / "arena_event_samples"\nARENA_EVENT_DIR.mkdir(parents=True, exist_ok=True)\nVISION_ADAPTIVE_FILE = PROFILE_DIR / "vision_adaptive.json"\n'''
    text = _replace_once(text, old, new, "event evidence directory")

    old = '''            "pilot_no_effect_fallback": 3,\n        },\n'''
    new = '''            "pilot_no_effect_fallback": 3,\n            "event_learning": True,\n            "event_change_bits": 11,\n            "event_cluster_bits": 8,\n            "event_cooldown_s": 0.45,\n            "event_max_clusters": 120,\n        },\n'''
    text = _replace_once(text, old, new, "event learning defaults")

    old = '''        "pilot_actions": {\n            "global": {},\n            "contexts": {},\n        },\n    }\n'''
    new = '''        "pilot_actions": {\n            "global": {},\n            "contexts": {},\n        },\n        "event_clusters": {},\n    }\n'''
    text = _replace_once(text, old, new, "event cluster state")

    old = '''                if isinstance(saved.get("pilot_actions"), dict):\n                    base["pilot_actions"] = saved["pilot_actions"]\n    except Exception:\n'''
    new = '''                if isinstance(saved.get("pilot_actions"), dict):\n                    base["pilot_actions"] = saved["pilot_actions"]\n                if isinstance(saved.get("event_clusters"), dict):\n                    base["event_clusters"] = saved["event_clusters"]\n    except Exception:\n'''
    text = _replace_once(text, old, new, "event cluster state load")

    old = '''def _arena_feature_vector(ref_screen):\n'''
    new = '''def _arena_event_signature(ref_screen):\n    """64-bit DCT perceptual signature of the calibrated enemy move region."""\n    try:\n        roi = opponent_move_roi()\n        region = crop(ref_screen, roi)\n        if region is None or region.size == 0:\n            return None\n        gray = cv2.cvtColor(region, cv2.COLOR_BGR2GRAY)\n        small = cv2.resize(gray, (32, 32), interpolation=cv2.INTER_AREA).astype(np.float32)\n        coeff = cv2.dct(small)[:8, :8].reshape(-1)\n        if len(coeff) != 64:\n            return None\n        body = coeff[1:]\n        threshold = float(np.median(body)) if len(body) else 0.0\n        value = 0\n        for index, item in enumerate(coeff):\n            bit = bool(item >= threshold) if index else False\n            value = (value << 1) | int(bit)\n        return int(value)\n    except Exception:\n        return None\n\n\ndef _arena_event_hamming(a, b):\n    if a is None or b is None:\n        return 64\n    try:\n        return int(int(a) ^ int(b)).bit_count()\n    except Exception:\n        try:\n            return bin(int(a) ^ int(b)).count("1")\n        except Exception:\n            return 64\n\n\ndef _arena_event_signature_from_node(node):\n    try:\n        raw = str((node or {}).get("signature") or "").strip().lower()\n        return int(raw, 16) if raw else None\n    except Exception:\n        return None\n\n\ndef _arena_event_evidence(ref_screen, cluster_id):\n    try:\n        roi = opponent_move_roi()\n        region = crop(ref_screen, roi)\n        if region is None or region.size == 0:\n            return None\n        max_w = 720\n        if region.shape[1] > max_w:\n            scale = max_w / float(region.shape[1])\n            region = cv2.resize(\n                region,\n                (max_w, max(1, int(round(region.shape[0] * scale)))),\n                interpolation=cv2.INTER_AREA,\n            )\n        name = f"{cluster_id}.jpg"\n        path = ARENA_EVENT_DIR / name\n        cv2.imwrite(str(path), region, [int(cv2.IMWRITE_JPEG_QUALITY), 80])\n        files = sorted(ARENA_EVENT_DIR.glob("EVT-*.jpg"), key=lambda p: p.stat().st_mtime)\n        for stale in files[:-120]:\n            try:\n                stale.unlink()\n            except Exception:\n                pass\n        return name\n    except Exception:\n        return None\n\n\ndef arena_record_enemy_event(ref_screen, signature, elapsed_s, heroes=None):\n    """Cluster a changed enemy visual state without pretending to know its name."""\n    if signature is None:\n        return None, False, None\n    state = get_arena_learning_state()\n    settings = state.get("settings") or {}\n    if not settings.get("event_learning", True):\n        return None, False, None\n    threshold = max(1, min(24, int(settings.get("event_cluster_bits") or 8)))\n    max_clusters = max(20, min(500, int(settings.get("event_max_clusters") or 120)))\n    new_cluster = False\n    best_id = None\n    best_distance = 65\n    with ARENA_LEARNING_LOCK:\n        clusters = arena_learning_state.setdefault("event_clusters", {})\n        for cluster_id, node in clusters.items():\n            old_sig = _arena_event_signature_from_node(node)\n            distance = _arena_event_hamming(signature, old_sig)\n            if distance < best_distance:\n                best_id, best_distance = str(cluster_id), int(distance)\n        if best_id is None or best_distance > threshold:\n            if len(clusters) >= max_clusters:\n                # Capacity is bounded. Keep learning counts on the nearest bucket\n                # rather than continuously creating unbounded animation noise.\n                if best_id is None:\n                    return None, False, None\n            else:\n                number = 1\n                while f"EVT-{number:04d}" in clusters:\n                    number += 1\n                best_id = f"EVT-{number:04d}"\n                best_distance = 0\n                clusters[best_id] = {\n                    "id": best_id,\n                    "label": None,\n                    "signature": f"{int(signature):016x}",\n                    "count": 0,\n                    "matches": 0,\n                    "wins": 0,\n                    "losses": 0,\n                    "heroes": {},\n                    "time_buckets": {},\n                    "first_seen": datetime.now().isoformat(timespec="seconds"),\n                    "last_seen": None,\n                    "evidence": None,\n                }\n                new_cluster = True\n        node = clusters.get(best_id)\n        if not isinstance(node, dict):\n            return None, False, None\n        node["count"] = int(node.get("count") or 0) + 1\n        node["last_seen"] = datetime.now().isoformat(timespec="seconds")\n        hero_counts = node.setdefault("heroes", {})\n        for hero in set(str(x) for x in (heroes or []) if str(x).strip()):\n            hero_counts[hero] = int(hero_counts.get(hero) or 0) + 1\n        bucket = _arena_time_bucket(elapsed_s)\n        bucket_counts = node.setdefault("time_buckets", {})\n        bucket_counts[bucket] = int(bucket_counts.get(bucket) or 0) + 1\n    if new_cluster:\n        evidence = _arena_event_evidence(ref_screen, best_id)\n        if evidence:\n            with ARENA_LEARNING_LOCK:\n                node = arena_learning_state.setdefault("event_clusters", {}).get(best_id)\n                if isinstance(node, dict):\n                    node["evidence"] = evidence\n    save_arena_learning_state()\n    return best_id, new_cluster, best_distance\n\n\ndef arena_apply_event_outcome(trace, result):\n    result = str(result or "").upper()\n    if result not in ("WIN", "LOSS") or not isinstance(trace, dict):\n        return\n    cluster_ids = {\n        str(event.get("cluster"))\n        for event in (trace.get("events") or [])\n        if isinstance(event, dict)\n        and event.get("kind") == "enemy_event"\n        and event.get("cluster")\n    }\n    if not cluster_ids:\n        return\n    with ARENA_LEARNING_LOCK:\n        clusters = arena_learning_state.setdefault("event_clusters", {})\n        for cluster_id in cluster_ids:\n            node = clusters.get(cluster_id)\n            if not isinstance(node, dict):\n                continue\n            node["matches"] = int(node.get("matches") or 0) + 1\n            key = "wins" if result == "WIN" else "losses"\n            node[key] = int(node.get(key) or 0) + 1\n    save_arena_learning_state()\n\n\ndef arena_event_summary(limit=8):\n    state = get_arena_learning_state()\n    rows = []\n    for cluster_id, node in (state.get("event_clusters") or {}).items():\n        if not isinstance(node, dict):\n            continue\n        matches = int(node.get("matches") or 0)\n        wins = int(node.get("wins") or 0)\n        losses = int(node.get("losses") or 0)\n        played = wins + losses\n        wr = (100.0 * wins / played) if played else None\n        rows.append({\n            "id": str(cluster_id),\n            "label": node.get("label"),\n            "count": int(node.get("count") or 0),\n            "matches": matches,\n            "wins": wins,\n            "losses": losses,\n            "win_rate": wr,\n            "evidence": node.get("evidence"),\n        })\n    rows.sort(key=lambda r: (-r["matches"], -r["count"], r["id"]))\n    return rows[:max(1, int(limit))]\n\n\ndef _arena_feature_vector(ref_screen):\n'''
    text = _replace_once(text, old, new, "event clustering helpers")

    old = '''        self._learning_quit_hits = 0\n        self._learning_last_report = None\n\n        # V7.3 Arena V2 Pilot state. Pilot only owns a match after its\n'''
    new = '''        self._learning_quit_hits = 0\n        self._learning_last_report = None\n        self._learning_last_enemy_event_sig = None\n        self._learning_last_enemy_event_at = 0.0\n\n        # V7.3 Arena V2 Pilot state. Pilot only owns a match after its\n'''
    text = _replace_once(text, old, new, "event engine state")

    old = '''        self._learning_quit_hits = 0\n        self._learning_last_report = None\n        with session_lock:\n'''
    new = '''        self._learning_quit_hits = 0\n        self._learning_last_report = None\n        self._learning_last_enemy_event_sig = _arena_event_signature(self._phone_safe_ref_for_event() if hasattr(self, "_phone_safe_ref_for_event") else None) if False else None\n        self._learning_last_enemy_event_at = 0.0\n        with session_lock:\n'''
    # Keep initialization deterministic; the intentionally-false expression avoids\n    # performing a capture and leaves the first live sample as the event baseline.\n    text = _replace_once(text, old, new, "event learning begin reset")

    old = '''        self._learning_last_signature = signature\n\n        sample = {\n'''
    new = '''        self._learning_last_signature = signature\n\n        event_sig = _arena_event_signature(ref_screen)\n        if event_sig is not None:\n            previous_event_sig = self._learning_last_enemy_event_sig\n            settings_event = (get_arena_learning_state().get("settings") or {})\n            change_bits = max(4, min(32, int(settings_event.get("event_change_bits") or 11)))\n            cooldown = max(0.20, float(settings_event.get("event_cooldown_s") or 0.45))\n            if previous_event_sig is None:\n                self._learning_last_enemy_event_sig = event_sig\n            else:\n                event_distance = _arena_event_hamming(previous_event_sig, event_sig)\n                if event_distance >= change_bits and elapsed - self._learning_last_enemy_event_at >= cooldown:\n                    with session_lock:\n                        event_heroes = list(session.get("current_detected_heroes") or [])\n                    cluster_id, is_new, cluster_distance = arena_record_enemy_event(\n                        ref_screen, event_sig, elapsed, event_heroes\n                    )\n                    if cluster_id:\n                        events = trace.setdefault("events", [])\n                        events.append({\n                            "t": round(elapsed, 3),\n                            "kind": "enemy_event",\n                            "cluster": cluster_id,\n                            "new_cluster": bool(is_new),\n                            "change_bits": int(event_distance),\n                            "cluster_bits": int(cluster_distance or 0),\n                        })\n                        if len(events) > 240:\n                            del events[:-240]\n                        if is_new:\n                            self.emit_log(\n                                f"ARENA LEARN: discovered {cluster_id} enemy visual event • evidence saved"\n                            )\n                        self._learning_last_enemy_event_at = elapsed\n                    self._learning_last_enemy_event_sig = event_sig\n\n        sample = {\n'''
    text = _replace_once(text, old, new, "event sample hook")

    old = '''        elif result in ("WIN", "LOSS"):\n            arena_train_from_trace(result, trace.get("samples") or [])\n        append_arena_learning_trace(trace)\n'''
    new = '''        elif result in ("WIN", "LOSS"):\n            arena_train_from_trace(result, trace.get("samples") or [])\n            arena_apply_event_outcome(trace, result)\n        append_arena_learning_trace(trace)\n'''
    text = _replace_once(text, old, new, "event outcome hook")

    old = '''        self._learning_trace = None\n        self._learning_quit_hits = 0\n        self._learning_last_signature = None\n        with session_lock:\n'''
    new = '''        self._learning_trace = None\n        self._learning_quit_hits = 0\n        self._learning_last_signature = None\n        self._learning_last_enemy_event_sig = None\n        self._learning_last_enemy_event_at = 0.0\n        with session_lock:\n'''
    text = _replace_once(text, old, new, "event finish reset")

    marker = "\n# V7.3 Arena Event Memory — unlabeled opponent move/card visual clusters build marker\n"
    if marker.strip() not in text:
        text += marker
    return text
